import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BLmRAsdY.js";var i=JSON.parse(`{"title":"文件树组件","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/file-tree.md","filePath":"zh-Hans/deep-dive/file-tree.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/file-tree.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="文件树组件" tabindex="-1">文件树组件 <a class="header-anchor" href="#文件树组件" aria-label="Permalink to “文件树组件”">​</a></h1><p>文件树是一个 SolidJS 组件，把同步任务数组可视化，并支持选中 / 取消选中任务。</p><h2 id="工作方式" tabindex="-1">工作方式 <a class="header-anchor" href="#工作方式" aria-label="Permalink to “工作方式”">​</a></h2><p>为不同的文件夹嵌套层级创建视觉层级（左侧内边距）。</p><p>渲染选择框、Obsidian 工具提示、图标和任务路径。</p><p>一条通用的路径压缩规则：</p><ul><li>如果某个文件夹在任务列表中只有一个子项，且文件夹本身不在任务列表中，子项与文件夹合并为一个条目，路径显示为 <code>&lt;parent-basename&gt; / &lt;child-basename&gt;</code>。这条规则适用于任意相邻的两段路径，因此连续的嵌套链可以连续合并，只在最浅的公共父级处停止。</li></ul><p>选择规则：</p><ul><li>取消一个删除任务会取消其祖先的删除文件夹任务；选中一个删除文件夹任务会选中其后代删除任务。</li><li>取消一个文件夹创建任务会取消其后代的创建任务；选中一个创建任务会选中其祖先的创建文件夹任务。</li><li>这些规则沿所有任务的祖先和后代级联。</li><li><code>Move</code> 任务遵循创建选择规则。</li><li>只要任何后代移动任务被取消，移动任务就表现为文件夹创建；转换由当前选择状态推导。</li></ul><p>行为：只有选中 / 取消选中，没有折叠，没有展开。</p><p>全选 / 全不选：</p><ul><li>这个选项以类似普通树节点的样式渲染，带复选框图标 <code>folders</code> 和对应的状态文本 <code>selectAll</code> 或 <code>deselectAll</code>，位置像树的根节点，在所有任务节点之上。</li><li>只要任何任务被选中，操作应为 <code>deselectAll</code>。只有没有任何任务被选中时，操作才是 <code>selectAll</code>。</li><li>任务被部分选中时，复选框应显示半选状态，否则显示已选 / 未选。</li></ul><h2 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to “实现”">​</a></h2><ol><li>预处理：</li></ol><p>先从任务路径构建前缀树，然后递归压缩单子项文件夹。展平后的可见树保存任务的祖先与后代链接，用于选择级联。</p><ol start="2"><li>渲染与选择：</li></ol><p>把压缩后的树展平为一维数组，并把节点存入 <code>Record</code>。选择状态保存在 Solid store 中；任务转换由该选择状态推导。</p><p>UI 只是对展平数组做映射，并按 depth 属性应用 padding-left。</p>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};